// ❌ OLD: Manual process signal listeners bypass NestJS's dependency tree,
// closing the database while active HTTP requests are still executing queries!
import { Injectable } from '@nestjs/common';

@Injectable()
export class DatabaseService {
  constructor() {
    process.on('SIGTERM', async () => {
      console.log('Closing DB connection...');
      await this.dbClient.close(); // ❌ Kills active queries in flight!
    });
  }
}

import { Injectable, OnModuleInit, OnApplicationShutdown } from '@nestjs/common';

@Injectable()
export class DatabaseService implements OnModuleInit, OnApplicationShutdown {
  // ✅ NEW: Guaranteed to run before the app accepts incoming HTTP traffic
  async onModuleInit() {
    await this.connectWithRetry();
  }

  // ✅ NEW: Guaranteed to run only AFTER the HTTP server stops accepting new connections
  async onApplicationShutdown(signal?: string) {
    console.log(`Received ${signal}, draining connection pool gracefully...`);
    await this.pool.drain();
    await this.pool.clear();
  }
}

